"use client"

import * as React from "react"
import { Maximize2, Minimize2 } from "lucide-react"

import { cn } from "@/lib/utils"

import {
  ChatComposerAction,
  ChatComposerContext,
  type ChatComposerInputAdapter,
} from "./chat-composer"

const reducedMotionQuery = "(prefers-reduced-motion: reduce)"

function subscribeToReducedMotion(callback: () => void) {
  const query = window.matchMedia(reducedMotionQuery)
  query.addEventListener("change", callback)
  return () => query.removeEventListener("change", callback)
}

/** Returns the live, server-safe reduced-motion preference. */
function useReducedMotion() {
  return React.useSyncExternalStore(
    subscribeToReducedMotion,
    () => window.matchMedia(reducedMotionQuery).matches,
    () => false,
  )
}

/** Parses a CSS duration token value into milliseconds. */
function cssDurationInMilliseconds(value: string, fallback: number) {
  const parsed = Number.parseFloat(value)
  if (!Number.isFinite(parsed)) return fallback
  return value.trim().endsWith("ms") ? parsed : parsed * 1000
}

/**
 * One revolution of iridescence wrapping the whole rim: the
 * Apple-Intelligence-style spectrum — amber through pink and purple into
 * cyan — decays continuously from the crisp near-white head all the way
 * around, faintest just behind the head's sharp cutoff. The stops are the
 * --nessa-chat-rim-* tokens, identical in both themes — a light source.
 */
const pillComposerRimSpinnerBaseClassName =
  "absolute left-1/2 top-1/2 aspect-square w-[200%] -translate-x-1/2 -translate-y-1/2"

/** The full-wrap trail: the spectrum decays around the whole revolution. */
const pillComposerRimTrailClassName =
  "bg-[conic-gradient(from_0deg,var(--nessa-chat-rim-0)_0deg,var(--nessa-chat-rim-1)_90deg,var(--nessa-chat-rim-2)_180deg,var(--nessa-chat-rim-3)_260deg,var(--nessa-chat-rim-4)_320deg,var(--nessa-chat-rim-head)_356deg,transparent_360deg)]"

/** The comet: a compact bright dart, the rest of the rim dark behind it. */
const pillComposerRimCometClassName =
  "bg-[conic-gradient(from_0deg,transparent_0deg,transparent_280deg,var(--nessa-chat-rim-3)_280deg,var(--nessa-chat-rim-4)_330deg,var(--nessa-chat-rim-head)_356deg,transparent_360deg)]"

/**
 * Masks a full-bleed layer down to an edge band: two stacked masks, the
 * inner clipped to the content box, composited away from the outer. The
 * mask only needs any opaque paint, so it borrows the foreground token.
 */
const pillComposerRimBandClassName =
  "[mask-image:linear-gradient(var(--foreground)_0_0),linear-gradient(var(--foreground)_0_0)] [mask-clip:content-box,border-box] [mask-composite:exclude] [-webkit-mask-image:linear-gradient(var(--foreground)_0_0),linear-gradient(var(--foreground)_0_0)] [-webkit-mask-clip:content-box,border-box] [-webkit-mask-composite:xor]"

// The spinner square is twice the pill's width, so rotating it never
// exposes a corner on any wider-than-tall pill.

export type PillComposerRimVariant = "orbit" | "comet" | "pulse" | "aurora"

/**
 * Why the composer is proposing an expansion change.
 *
 * A host that answers some of them differently gets to say which without
 * inferring it from timing: `"submit"` is the one a host that turned its own
 * send away is likely to decline, and the rest are the ways a person leaves
 * the pane or has it taken from them.
 */
export type PillComposerExpansionReason =
  /** The expand/minimize control in the pane's corner. */
  | "control"
  /** Escape, while expanded. */
  | "escape"
  /** The form was submitted. */
  | "submit"
  /** `expandable` went false with a request standing. */
  | "withdrawal"

/**
 * The traveling-light overlay: a thin crisp gradient band on the pill's
 * rim, plus a blurred copy bleeding a few pixels inward as a soft glow —
 * nothing renders outside the pill. It fades in and out with `active` and
 * keeps animating until the fade-out finishes, so toggling reads as the
 * light dimming, not stopping. The motion itself comes in structurally
 * distinct variants: `orbit` revolves the full decaying trail, `comet`
 * laps a compact bright dart around an otherwise dark rim, `pulse` holds
 * the lit rim still and breathes, and `aurora` never revolves — the
 * full-wrap spectrum morphs hue in place under a slow intensity wave.
 */
function PillComposerRim({
  active,
  variant = "orbit",
}: {
  active: boolean
  variant?: PillComposerRimVariant
}) {
  const reducedMotion = useReducedMotion()
  const [present, setPresent] = React.useState(false)
  const wrapperRef = React.useRef<HTMLSpanElement>(null)
  const ringSpinRef = React.useRef<HTMLSpanElement>(null)
  const glowSpinRef = React.useRef<HTMLSpanElement>(null)

  React.useEffect(() => {
    // With reduced motion the opacity transition is suppressed, so no
    // transitionend will retire the presence flag; mirror `active` directly.
    if (active || reducedMotion) {
      setPresent(active)
      return
    }
    // A fade-out with a zeroed duration token never fires transitionend
    // either — retire the flag immediately, matching the spin effect's
    // zero-duration guards.
    const node = wrapperRef.current
    if (!node) return
    const duration = cssDurationInMilliseconds(
      getComputedStyle(node).transitionDuration,
      0,
    )
    if (duration === 0) setPresent(false)
  }, [active, reducedMotion])

  const spinning = present && !reducedMotion
  React.useEffect(() => {
    const ring = ringSpinRef.current
    const glow = glowSpinRef.current
    if (!ring || !glow || !spinning) return
    const ambient = cssDurationInMilliseconds(
      getComputedStyle(ring).getPropertyValue("--nessa-motion-duration-ambient"),
      3200,
    )
    if (ambient === 0) return
    if (typeof ring.animate !== "function") return
    const spin = [{ rotate: "0deg" }, { rotate: "360deg" }]
    const animations: Animation[] = []
    if (variant === "orbit") {
      const options = { duration: ambient, easing: "linear", iterations: Infinity }
      animations.push(ring.animate(spin, options), glow.animate(spin, options))
    }
    if (variant === "comet") {
      // A compact dart lapping fast — most of the rim stays dark behind it.
      const options = {
        duration: ambient * 0.45,
        easing: "linear",
        iterations: Infinity,
      }
      animations.push(ring.animate(spin, options), glow.animate(spin, options))
    }
    if (variant === "pulse") {
      const options = {
        duration: ambient / 2,
        easing: "ease-in-out",
        iterations: Infinity,
      }
      animations.push(
        ring.animate(
          [{ opacity: 1 }, { opacity: 0.45 }, { opacity: 1 }],
          options,
        ),
        glow.animate(
          [{ opacity: 0.35 }, { opacity: 0.12 }, { opacity: 0.35 }],
          options,
        ),
      )
    }
    if (variant === "aurora") {
      // No revolution at all: the full-wrap spectrum stays put while its
      // hues cycle and the intensity waves — colors morphing in place.
      const hueOptions = {
        duration: ambient * 1.2,
        easing: "linear",
        iterations: Infinity,
      }
      const waveOptions = {
        duration: ambient,
        easing: "ease-in-out",
        iterations: Infinity,
      }
      animations.push(
        ring.animate(
          [{ filter: "hue-rotate(0deg)" }, { filter: "hue-rotate(360deg)" }],
          hueOptions,
        ),
        // The glow's blur rides along in the keyframes: animating `filter`
        // replaces the class value for the animation's duration.
        glow.animate(
          [
            { filter: "blur(6px) hue-rotate(0deg)" },
            { filter: "blur(6px) hue-rotate(360deg)" },
          ],
          hueOptions,
        ),
        ring.animate(
          [{ opacity: 1 }, { opacity: 0.65 }, { opacity: 1 }],
          waveOptions,
        ),
      )
    }
    return () => animations.forEach((animation) => animation.cancel())
  }, [spinning, variant])

  return (
    <span
      ref={wrapperRef}
      aria-hidden="true"
      data-slot="pill-composer-rim"
      data-active={active || undefined}
      data-variant={variant}
      onTransitionEnd={(event) => {
        if (event.target === event.currentTarget && !active) setPresent(false)
      }}
      onTransitionCancel={(event) => {
        // A fade-out interrupted by display:none (hidden panel, switched
        // tab) cancels instead of ending — retire the flag so the infinite
        // spin animations do not run forever on an invisible overlay.
        if (event.target === event.currentTarget && !active) setPresent(false)
      }}
      className="pointer-events-none absolute -inset-px z-10 rounded-[inherit] opacity-0 transition-opacity [transition-duration:var(--nessa-motion-duration-normal)] [transition-timing-function:var(--nessa-motion-easing-standard)] data-[active]:opacity-100 motion-reduce:transition-none"
    >
      <span
        data-slot="pill-composer-rim-glow"
        className={cn(
          "absolute inset-0 overflow-hidden rounded-[inherit] p-[5px]",
          pillComposerRimBandClassName,
        )}
      >
        <span
          ref={glowSpinRef}
          className={cn(
            pillComposerRimSpinnerBaseClassName,
            variant === "comet"
              ? pillComposerRimCometClassName
              : pillComposerRimTrailClassName,
            "blur-[6px] opacity-35",
          )}
        />
      </span>
      <span
        data-slot="pill-composer-rim-ring"
        className={cn(
          "absolute inset-0 overflow-hidden rounded-[inherit] p-[2px]",
          pillComposerRimBandClassName,
        )}
      >
        <span
          ref={ringSpinRef}
          className={cn(
            pillComposerRimSpinnerBaseClassName,
            variant === "comet"
              ? pillComposerRimCometClassName
              : pillComposerRimTrailClassName,
          )}
        />
      </span>
    </span>
  )
}

/** A compact pill-shaped message-entry form with a traveling-light working state. */
export interface PillComposerProps extends React.ComponentProps<"form"> {
  /**
   * Shows the iridescent light traveling the pill's rim while the agent
   * works. Toggling fades the light in and out rather than switching it.
   */
  generating?: boolean
  /** Chooses the rim's motion while generating. Defaults to `orbit`. */
  rimVariant?: PillComposerRimVariant
  /** Sets the preferred width in CSS pixels while preserving host containment. */
  width?: number
  /** Offers a three-line expand control that fills the nearest positioned ancestor. */
  expandable?: boolean
  /**
   * Whether the full-pane editor is open, when the host owns that state.
   * Leave undefined to let the composer own it.
   */
  expanded?: boolean
  /** Whether the full-pane editor starts open, when the composer owns the state. */
  defaultExpanded?: boolean
  /**
   * Called whenever the composer would change expansion, with why. A
   * controlled host decides what to do with each; an uncontrolled one can use
   * this to follow along.
   */
  onExpandedChange?: (
    expanded: boolean,
    reason: PillComposerExpansionReason,
  ) => void
  submitOnEnter?: boolean
}

/**
 * Renders the pill form and provides the ChatComposer slot context, so
 * ChatComposerInput, ChatComposerAttachments, ChatComposerAction, and
 * ChatComposerTrigger compose inside it unchanged. Lay the single control
 * row out with PillComposerRow; attachments stack above it and round the
 * pill's corners as it grows. Multiline inputs use rounded rectangular corners.
 * With expandable, three rendered lines reveal a control that fills the nearest
 * positioned ancestor; Escape, Minimize, or sending the message restores the
 * compact editor without remounting it. Hosts define that ancestor to bound
 * expansion to a chat pane, and a host that needs to decide for itself when the
 * pane opens and closes controls `expanded` and follows `onExpandedChange`.
 */
function PillComposer({
  generating = false,
  rimVariant = "orbit",
  width,
  submitOnEnter = true,
  expandable = false,
  expanded: expandedProp,
  defaultExpanded = false,
  onExpandedChange,
  onKeyDown,
  onSubmit,
  className,
  children,
  style,
  ...props
}: PillComposerProps) {
  const [inputAdapter, setInputAdapter] =
    React.useState<ChatComposerInputAdapter | null>(null)
  const [multiline, setMultiline] = React.useState(false)
  const [canExpand, setCanExpand] = React.useState(false)
  // Expansion is the composer's unless a host claims it. A host that passes
  // `expanded` owns every transition and is told about each one through
  // `onExpandedChange`; a host that passes neither gets the behaviour below
  // and can still follow along through the same callback.
  const [selfExpanded, setSelfExpanded] = React.useState(defaultExpanded)
  const controlled = expandedProp !== undefined
  const expandRequested = expandedProp ?? selfExpanded
  // Expansion is the host's to withdraw. When `expandable` goes false — a
  // responsive breakpoint dropping the affordance, say — the full-pane
  // layout has to come down with the control that exits it; otherwise the
  // person is left inside an overlay whose only way out is Escape. Derived
  // rather than only reset in an effect, so the collapse lands in the same
  // commit as the prop change instead of a frame later.
  const expanded = expandable && expandRequested
  // One door for every transition, so a controlled host hears about the ones
  // the composer starts by itself — the withdrawal below and the collapse on
  // submit — and not only the ones a person clicks.
  const changeExpanded = React.useCallback(
    (next: boolean, reason: PillComposerExpansionReason) => {
      if (!controlled) setSelfExpanded(next)
      onExpandedChange?.(next, reason)
    },
    [controlled, onExpandedChange],
  )
  // And the request itself is dropped, so re-enabling `expandable` does not
  // reopen the pane without anyone asking for it.
  //
  // Asked once per withdrawal, not once per callback identity. A controlled
  // host that declines this and records it — to show what happened, say —
  // rerenders, hands back a fresh `onExpandedChange`, and would otherwise be
  // asked again by that identity change alone, with its own recording feeding
  // the next round. The guard clears the moment expansion is offered again or
  // the request goes away, so the next withdrawal is a fresh episode and is
  // asked for in its own right.
  const asked = React.useRef(false)
  React.useEffect(() => {
    if (expandable || !expandRequested) {
      asked.current = false
      return
    }
    if (asked.current) return
    asked.current = true
    changeExpanded(false, "withdrawal")
  }, [expandable, expandRequested, changeExpanded])

  // Measure rendered lines, including wrapping and font/width changes. Keep
  // the input width and control positions stable so changing the corners
  // cannot itself trigger another expansion/collapse.
  React.useLayoutEffect(() => {
    const input = inputAdapter?.element
    if (!input) return
    const measure = () => {
      const css = getComputedStyle(input)
      const padding = parseFloat(css.paddingTop) + parseFloat(css.paddingBottom)
      const lines = (input.clientHeight - padding) / parseFloat(css.lineHeight)
      setMultiline(lines > 1.5)
      setCanExpand(lines > 2.5)
    }
    measure()
    if (typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(measure)
    observer.observe(input)
    return () => observer.disconnect()
  }, [inputAdapter])

  // The pill reads as `constrained` so ChatComposerInput drops its min-height
  // floor and hugs a single line, growing only with content; the attachments
  // row inherits its scroll cap the same way.
  const context = React.useMemo(
    () => ({
      composerMaxHeight: undefined,
      constrained: true,
      submitOnEnter,
      size: "compact" as const,
      inputAdapter,
      registerInput: setInputAdapter,
    }),
    [inputAdapter, submitOnEnter],
  )

  return (
    <ChatComposerContext.Provider value={context}>
      <form
        data-slot="pill-composer"
        data-multiline={multiline || undefined}
        data-expanded={expanded || undefined}
        onKeyDown={(event) => {
          onKeyDown?.(event)
          if (!event.defaultPrevented && event.key === "Escape" && expanded) {
            event.preventDefault()
            changeExpanded(false, "escape")
            inputAdapter?.element.focus()
          }
        }}
        onSubmit={(event) => {
          onSubmit?.(event)
          // Sending is the end of writing. The full-pane editor is there to
          // draft a long message, and once that message is gone there is
          // nothing left in it to draft — what stays behind is an empty sheet
          // over the transcript, hiding the reply it was opened to write to.
          // A host that needs the pane to survive its own submit — one that
          // turns the send away, say — controls `expanded` and declines this.
          if (expandRequested) changeExpanded(false, "submit")
        }}
        data-generating={generating || undefined}
        aria-busy={generating || undefined}
        className={cn(
          // No focus-within ring or border shift: the caret carries focus, as
          // in ChatComposer's borderMode "none" (owner preference, Aug 2026).
          // A bottom-anchored input must not become the scroll anchor of an
          // outer document: preserving its moving top edge scrolls the page
          // and makes upward growth appear to push the composer downward.
          "relative flex min-w-0 w-full max-w-full flex-col gap-1.5 [overflow-anchor:none] rounded-[1.625rem] border border-border bg-card p-1.5 font-sans text-card-foreground",
          (multiline || expanded) && "rounded-2xl",
          expanded && "absolute inset-0 z-10 min-h-0 [&>[data-slot=pill-composer-row]]:min-h-0 [&>[data-slot=pill-composer-row]]:flex-1 [&_[data-slot=chat-composer-markdown-editor]]:h-full [&_[data-slot=chat-composer-markdown-editor]]:max-h-none! [&_[data-slot=chat-composer-editor]]:h-full [&_[data-slot=chat-composer-editor]]:max-h-none! [&_[data-slot=chat-composer-editor]]:self-stretch! [&_[data-slot=chat-composer-input]]:h-full! [&_[data-slot=chat-composer-input]]:max-h-none! [&_[data-slot=chat-composer-input]]:self-stretch!",
          className,
        )}
        style={{
          ...style,
          ...(expanded ? { width: "100%" } : width === undefined ? undefined : { width: `min(${width}px, 100%)` }),
        }}
        {...props}
      >
        <PillComposerRim active={generating} variant={rimVariant} />
        {expandable && (canExpand || expanded) && (
          <div data-slot="pill-composer-expand-control" className="absolute right-1.5 top-1.5 z-10">
            <ChatComposerAction
              aria-label={expanded ? "Minimize composer" : "Expand composer"}
              title={expanded ? "Minimize composer" : "Expand composer"}
              aria-expanded={expanded}
              onClick={() => {
                changeExpanded(!expanded, "control")
                inputAdapter?.element.focus()
              }}
            >
              {expanded ? <Minimize2 aria-hidden="true" className="opacity-70" /> : <Maximize2 aria-hidden="true" className="opacity-70" />}
            </ChatComposerAction>
          </div>
        )}
        {children}
      </form>
    </ChatComposerContext.Provider>
  )
}

/** Lays out the pill's single control row: leading actions, input, trailing actions. */
function PillComposerRow({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="pill-composer-row"
      className={cn("flex min-w-0 max-w-full items-end gap-1", className)}
      {...props}
    />
  )
}

export { PillComposer, PillComposerRow }
